// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Caller address
        address alice = address(0xABCD);
        vm.deal(alice, 1);
        vm.prank(alice);
        c.deposit{value: 1}();

        // Assert that after deposit, balance of alice is exactly 1.
        // Reference: balances[alice] == 1; Bug: balances[alice] == 2 (so this fails)
        assertTrue(c.balances(alice) == 1);
    }
}

