pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.deposit{value: 1 wei}();
        vm.prank(user);
        bool ok;
        try c.withdraw(1 wei) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonCreator = address(0x123);
        vm.deal(nonCreator, 1 ether);
        vm.prank(nonCreator);
        c.deposit{value: 1 ether}();

        bool ok = false;
        try c.migrateTo(nonCreator) { ok = true; } catch { ok = false; }
        assertTrue(ok == false);
    }
}

